"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[8587],{3325:e=>{e.exports=JSON.parse('{"tag":{"label":"scenario","permalink":"/pr-preview/pr-10/docs/next/tags/scenario","allTagsPath":"/pr-preview/pr-10/docs/next/tags","count":4,"items":[{"id":"tutorials/conversational-game","title":"Scenario, a conversational game","description":"A guessing game is the simplest LEIA and a good first activity for a class that has never used the platform. The example is a secret word game. The character thinks of a word, the student asks questions that can only be answered with yes or no, and wins by naming the word.","permalink":"/pr-preview/pr-10/docs/next/tutorials/conversational-game"},{"id":"tutorials/multi-leia-simulation","title":"Scenario, a group simulation with several LEIAs","description":"In a MultiLEIA activity the student talks to several characters in the same chat. An orchestrator decides which character answers each message, so a meeting with a client and an IT manager, a focus group of users or a team retrospective become possible. The example puts Helen Park, the library manager, and Omar Haddad, the IT manager of the university, in one requirements meeting.","permalink":"/pr-preview/pr-10/docs/next/tutorials/multi-leia-simulation"},{"id":"tutorials/programming-exercise","title":"Scenario, a programming exercise with the code editor","description":"A LEIA with the Editor widget becomes a programming tutor. The student writes code in an editor next to the chat, the LEIA reads it, comments on it and runs the tests you defined. The example is the FizzBuzz function in Python with Ada Okafor, a patient tutor who asks guiding questions instead of giving the answer.","permalink":"/pr-preview/pr-10/docs/next/tutorials/programming-exercise"},{"id":"tutorials/requirements-elicitation","title":"Scenario, a requirements elicitation interview","description":"The classic LEIA. The student plays the analyst, the LEIA plays a client who knows what they need but does not know how to say it, and the deliverable is a model of what the student discovered. The example used throughout the teacher guide is Helen Park, the manager of a small university library who wants a room booking and lending application.","permalink":"/pr-preview/pr-10/docs/next/tutorials/requirements-elicitation"}],"unlisted":false}}')}}]);